descriptor.controllerScript:
self.onInit = function () {
  // Inject Tailwind once
  if (!document.getElementById('tailwindcss')) {
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    document.head.appendChild(script);
  }

  // Default values
  self.cpu_usage = 0;
  self.ram_usage = 0;
  self.device_temperature = 0;

  // 🔁 Subscribe to telemetry
  self.subscription = self.ctx.subscriptionApi.createSubscription({
    type: 'latest', // or 'timeseries' for historical data
    datasources: [
      {
        type: 'entity',
        entityType: 'DEVICE',
        entityId: '<<DEVICE_ID>>', // Replace this with real entity UUID
        dataKeys: [
          { name: 'cpu_usage', type: 'timeseries' },
          { name: 'ram_usage', type: 'timeseries' },
          { name: 'device_temperature', type: 'timeseries' }
        ]
      }
    ],
    callbacks: {
      onDataUpdated: function (data) {
        data.forEach(dp => {
          const key = dp.dataKey.name;
          const latest = dp.data[dp.data.length - 1];
          if (!latest) return;

          const val = parseFloat(latest[1]).toFixed(2);
          const ts = new Date(latest[0]).toLocaleTimeString();

          self[key] = val;
          self[`${key}_ts`] = ts;
        });
        self.ctx.detectChanges(); // Refresh HTML binding
      },
      onSubscriptionReady: function () {
        console.log('✅ Subscription Ready');
      },
      onSubscriptionError: function (error) {
        console.error('❌ Subscription error:', error);
      }
    }
  });
};

